CREATE TYPE "AssetStatus" AS ENUM ('STAGED','READY','REJECTED','DELETING','DELETED');
CREATE TABLE "FileAsset" ("id" uuid PRIMARY KEY,"storageKey" text NOT NULL UNIQUE,"contentHash" varchar(64) NOT NULL,"mediaType" varchar(50) NOT NULL,"byteSize" integer NOT NULL,"width" integer NOT NULL,"height" integer NOT NULL,"status" "AssetStatus" NOT NULL DEFAULT 'STAGED',"creatorId" uuid NOT NULL REFERENCES "User"("id"),"createdAt" timestamptz NOT NULL DEFAULT now(),"validatedAt" timestamptz,"rejectedCode" varchar(80));
CREATE TABLE "ProductImage" ("id" uuid PRIMARY KEY,"productId" uuid NOT NULL REFERENCES "Product"("id"),"assetId" uuid NOT NULL REFERENCES "FileAsset"("id"),"contentHash" varchar(64) NOT NULL,"position" integer NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("productId","contentHash"),UNIQUE("productId","position"));
